import numpy as np
# binary 8=1, 9=0, glyph/blank=nan
D1L=np.array([[1,0,0],[2,-1,-1],[0,1,0]])
D1R=np.array([[0,1,0],[0,1,0],[2,0,0]])
D1C=np.array([[0,-1,-1],[1,2,1],[-1,1,0]])
D2L=np.array([[1,0,0],[1,2,1],[0,0,1]])
D2R=np.array([[0,1,0],[2,1,0],[0,1,1]])
D2C=np.array([[1,0,-1],[1,2,1],[1,0,-1]])
D3L=np.array([[0,1,0],[1,2,0],[0,1,1]])
D3R=np.array([[1,0,0],[1,2,1],[0,0,1]])
D3C=np.array([[1,0,0],[1,2,1],[1,0,0]])
# test boolean output where neither special involved, all dihedral transforms of one matrix, and ops
ops={'xor':lambda a,b:a^b,'or':lambda a,b:a|b,'and':lambda a,b:a&b,'xnor':lambda a,b:1^(a^b),'a':lambda a,b:a,'b':lambda a,b:b,'not_a':lambda a,b:1-a,'not_b':lambda a,b:1-b,'a_notb':lambda a,b:a&(1-b),'b_nota':lambda a,b:b&(1-a)}
def trans(a,k):
    if k<4:return np.rot90(a,k)
    return np.rot90(np.fliplr(a),k-4)
for side in ['L','R']:
  for k in range(8):
    for name,op in ops.items():
      err=0;n=0
      for di in range(1,4):
        L,R,C=eval(f'D{di}L'),eval(f'D{di}R'),eval(f'D{di}C')
        A,B=(L,trans(R,k)) if side=='R' else (trans(L,k),R)
        mask=(A<=1)&(B<=1)&(C<=1)
        pred=op(A,B)
        err+=np.sum(pred[mask]!=C[mask]);n+=mask.sum()
      if err<=2:print(side,k,name,err,n)
